<template>
<div class="spt" v-if="s">
  <div class="banner" :class="{prod:s.mode!=='demo'}">{{s.mode==='demo'?'DEMO MODE — Simulated Data':'PRODUCTION — chờ adapter F06.1'}}</div>
  <div class="heading"><div><span class="eyebrow">SMART POSTURE TRACKER</span><h1>{{title}}</h1></div><div class="badges"><span>{{s.connection==='online'?'● Online':'● Offline'}}</span><span>{{s.session==='active'?'Phiên đang đo':'Chưa có phiên'}}</span></div></div>
  <div v-if="s.error" class="alert" role="alert">{{s.error}}</div><div v-if="s.notice" class="notice">{{s.notice}}</div>
  <template v-if="page==='Dashboard'">
    <div class="session-strip card">
      <div class="session-clock"><span class="metric-icon">◷</span><div><small>Phiên hiện tại</small><strong>{{s.pending?'Đang chờ xác nhận':s.session==='active'?duration(Date.now()-s.started):'Sẵn sàng'}}</strong><p>Đo hợp lệ: {{duration(s.validMs)}}</p></div></div>
      <div class="actions session-actions"><button @click="command('START_SESSION')" :disabled="!!s.pending || s.session!=='idle'">▶ &nbsp; Bắt đầu phiên</button><button class="secondary" @click="command('STOP_SESSION')" :disabled="!!s.pending || s.session!=='active'">■ &nbsp; Kết thúc phiên</button></div>
      <div class="sensor-strip"><span v-for="n in 4" :key="n" :class="{unavailable:s.sensorStatus?.[n-1]!=='ok'}"><i></i>P{{n}}</span><small>Cập nhật {{date(s.updated)}}</small></div>
    </div>
    <div class="dashboard-layout">
      <div class="dashboard-main">
        <div class="card curve"><div class="card-heading"><div><span class="eyebrow">MÔ PHỎNG 2D</span><h2>Đường cong bề mặt lưng</h2></div><span class="data-badge" :class="{unavailable:!s.valid}">{{s.valid?'● Dữ liệu hợp lệ':'● Không đủ dữ liệu'}}</span></div>
          <div class="curve-body"><div class="curve-description"><span class="curve-mark">◌</span><h3>Theo dõi theo vùng</h3><p>Bốn vị trí từ lưng trên đến lưng dưới, nối bằng ba đoạn cong ước lượng.</p><label class="reference-toggle"><input type="checkbox" v-model="showReference"> Hiện mốc cá nhân</label><div class="curve-legend"><span><i class="legend-line"></i> Hiện tại</span><span v-if="s.reference"><i class="legend-line reference"></i> Mốc cá nhân</span></div></div>
            <div v-if="!s.valid || s.mode!=='demo'" class="empty curve-empty">Không đủ dữ liệu hợp lệ để dựng đường cong.</div>
            <svg v-else viewBox="-120 -240 260 260" aria-label="Đường cong bề mặt lưng từ P4 đến P1"><defs><pattern id="curve-grid" width="40" height="40" patternUnits="userSpaceOnUse"><path d="M 40 0 L 0 0 0 40" fill="none" stroke="#e5e8f2" stroke-width=".7"/></pattern></defs><rect x="-120" y="-240" width="260" height="260" fill="url(#curve-grid)"/><line x1="0" y1="-240" x2="0" y2="20" stroke="#ccd2e6" stroke-width="1" stroke-dasharray="3 4"/><path v-if="showReference && refCurve" :d="refCurve.path" class="refline"/><path :d="curve.path" class="livepath"/><g v-for="(pt,i) in curve.points" :key="i"><circle :cx="pt[0]" :cy="pt[1]" r="3.4"/><text :x="pt[0]+9" :y="pt[1]+2">P{{4-i}}</text></g></svg>
          </div><p class="curve-disclaimer">Mô phỏng đường cong bề mặt lưng 2D ước lượng — không phải kết quả chẩn đoán y khoa.</p>
        </div>
        <div class="card signal-card"><div class="card-heading"><div><span class="eyebrow">TÍN HIỆU GẦN ĐÂY</span><h2>Góc theo thời gian</h2></div><span class="muted">Tối đa 120 mẫu</span></div><div class="series"><label v-for="(n,i) in names" :key="n"><input type="checkbox" v-model="selected" :value="i"> {{n}}</label></div><div class="plot-wrap"><span class="plot-unit">Góc (°)</span><div class="signal-chart"><div class="y-labels" aria-hidden="true"><span>30°</span><span>0°</span><span>−30°</span></div><svg class="timeline" viewBox="0 0 600 180" preserveAspectRatio="none" aria-label="Diễn biến các góc theo thời gian"><line v-for="y in [30,60,90,120,150]" :key="y" x1="0" :y1="y" x2="600" :y2="y" stroke="#e4e8ee" stroke-width="1"/><path v-for="i in selected" :key="i" :d="timeline(i)" fill="none" :stroke="colors[i]" stroke-width="2"/></svg></div><div class="chart-axis"><span>{{timeLabel(s.samples?.[0]?.t)}}</span><span>{{timeLabel(s.samples?.[s.samples.length-1]?.t)}}</span></div></div><div class="legend"><span v-for="i in selected" :key="i" :style="{color:colors[i]}">● {{names[i]}} </span></div><p class="muted">Khoảng trống thể hiện dữ liệu thiếu hoặc không hợp lệ.</p></div>
      </div>
      <div class="dashboard-side">
        <div class="card angles-panel"><div class="card-heading"><div><span class="eyebrow">BỐN VỊ TRÍ</span><h2>Góc nghiêng Pitch</h2></div><span class="muted">Đơn vị: °</span></div><div class="pitch-tiles"><div class="pitch-tile" v-for="(name,i) in ['Lưng trên','Giữa trên','Giữa dưới','Lưng dưới']" :key="name"><small>P{{i+1}}</small><strong>{{finite(s.pitch?.[i])?fmt(s.pitch[i])+'°':'—'}}</strong><span>{{name}}</span><span v-if="s.reference && finite(s.pitch?.[i])">Δ mốc {{fmt(s.pitch[i]-s.reference.pitch[i])}}°</span><span v-if="!finite(s.pitch?.[i])" class="missing-label">Mất dữ liệu</span></div></div><div class="relative-title">Góc tương đối giữa các vùng</div><div class="relative-tiles"><div v-for="(name,i) in ['P1 − P2','P2 − P3','P3 − P4']" :key="name"><small>{{name}}</small><strong>{{finite(s.relative?.[i])?fmt(s.relative[i])+'°':'—'}}</strong></div></div></div>
        <div class="card reminder-panel"><div class="card-heading"><div><span class="eyebrow">THIẾT BỊ</span><h2>Nhắc rung</h2></div><span class="data-badge" :class="{unavailable:!s.reminder}">{{s.reminder?'Đang bật':'Đang tắt'}}</span></div><p>Điều khiển nhắc nhở cho phiên đo hiện tại.</p><div class="reminder-details"><div><small>Ngưỡng demo</small><b>{{s.demoSettings?.trigger ?? '—'}}°</b></div><div><small>Thời gian chờ</small><b>{{s.demoSettings?.hold ?? '—'}} giây</b></div></div><div class="actions reminder-actions"><button class="secondary" @click="command('SET_REMINDER',{enabled:!s.reminder})" :disabled="!!s.pending">{{s.reminder?'Tắt':'Bật'}} nhắc rung</button><button @click="command('TEST_VIBRATION')" :disabled="!!s.pending">Kiểm tra rung</button></div><p class="muted">Các nút trong demo gửi lệnh mô phỏng và chờ ACK giả lập.</p></div>
        <div class="card connection-card"><span class="eyebrow">TRẠNG THÁI THIẾT BỊ</span><h2>{{s.connection==='online'?'Đang kết nối':'Chưa kết nối'}}</h2><p>{{s.deviceId||'Chưa chọn thiết bị'}} · {{s.valid?'Đủ bốn cảm biến':'Kiểm tra cảm biến'}}</p></div>
      </div>
    </div>
    <div v-if="s.mode==='demo'" class="card"><h2>Kịch bản demo</h2><div class="actions"><button class="secondary" v-for="x in scenarios" :key="x[0]" @click="dispatch({kind:'scenario',value:x[0]})">{{x[1]}}</button></div><label>Phản hồi lệnh <select :value="s.ackMode" @change="dispatch({kind:'ackMode',value:$event.target.value})"><option value="success">ACK thành công</option><option value="rejected">ACK từ chối</option><option value="timeout">Timeout</option></select></label></div>
  </template>
  <template v-if="page==='History'">
    <div class="section"><div><span class="eyebrow">NHẬT KÝ PHIÊN ĐO</span><h2>Nhìn lại các phiên của bạn</h2></div><span class="muted">{{filtered.length}} phiên</span></div>
    <div class="card history-list"><div class="section compact"><div><h2>Danh sách phiên</h2><p>Chọn một phiên để xem chi tiết và dữ liệu đã ghi.</p></div><div class="actions"><label>Từ ngày <input type="date" v-model="from"></label><label>Đến ngày <input type="date" v-model="to"></label></div></div>
      <div v-if="!filtered.length" class="empty">Chưa có phiên trong khoảng thời gian này.</div>
      <button v-for="h in filtered" :key="h.id" class="history-row" :class="{active:chosen && chosen.id===h.id}" @click="chooseSession(h)"><span class="session-icon">↗</span><span class="session-main"><b>{{h.id}}</b><small>{{date(h.started)}}</small></span><span class="session-time">{{duration(h.ended-h.started)}}<small>Thời gian phiên</small></span><span class="session-time">{{duration(h.validMs)}}<small>Dữ liệu hợp lệ</small></span><span class="session-link">Xem chi tiết →</span></button>
    </div>
    <template v-if="chosen"><div class="section"><div><span class="eyebrow">CHI TIẾT PHIÊN</span><h2>{{chosen.id}}</h2><p class="muted">{{date(chosen.started)}} — {{date(chosen.ended)}}</p></div><span class="status-pill">{{chosen.status || 'Đã kết thúc'}}</span></div>
      <div class="grid metrics"><div class="card"><small>Thời gian đo</small><strong>{{duration(chosen.ended-chosen.started)}}</strong><p>Tổng thời gian phiên</p></div><div class="card"><small>Hợp lệ</small><strong>{{duration(chosen.validMs)}}</strong><p>Không tính thời gian thiếu</p></div><div class="card"><small>Sự kiện</small><strong>{{chosen.events || 0}}</strong><p>Sự kiện vượt ngưỡng</p></div><div class="card"><small>Nhắc rung</small><strong>{{chosen.vibrations || 0}}</strong><p>Số lần mô phỏng</p></div></div>
      <div class="grid two"><div class="card"><h2>Diễn biến góc trong phiên</h2><p>Pitch bốn cảm biến · dữ liệu đã lưu</p><svg class="timeline" viewBox="0 0 600 180" preserveAspectRatio="none"><line x1="0" y1="90" x2="600" y2="90" stroke="#dbe4ea"/><path v-for="i in 4" :key="i" :d="historyLine(chosen,i-1)" fill="none" :stroke="colors[i-1]" stroke-width="2.5"/></svg><div class="legend"><span v-for="i in 4" :key="i" :style="{color:colors[i-1]}">● P{{i}}　</span></div><div class="chart-axis"><span>{{date(chosen.started)}}</span><span>{{date(chosen.ended)}}</span></div></div>
      <div class="card"><h2>Phân bố độ lệch P1</h2><p>So với mốc cá nhân · tổng {{duration(binTotal)}}</p><div v-if="!chosen.reference" class="empty">Không có mốc cá nhân cho phiên này.</div><div v-else v-for="(b,i) in bins" :key="i" class="bin"><span>{{['0–5°','5–10°','10–15°','15–20°','20–25°','≥25°'][i]}}</span><div><i :style="{width:(binTotal?100*b/binTotal:0)+'%'}"></i></div><span>{{(b/60000).toFixed(2)}} phút · {{binTotal?(100*b/binTotal).toFixed(1):0}}%</span></div><p class="muted">Các nhóm góc chỉ để quan sát, không phải đánh giá y khoa.</p></div></div>
      <div class="card"><h2>Góc theo cảm biến</h2><p>Trung bình và lớn nhất trong các mẫu hợp lệ đã lưu.</p><div class="grid pitch"><div v-for="n in 4" :key="n" class="angle-summary"><small>P{{n}}</small><strong>{{sessionAverage(chosen,n-1)}}°</strong><span>Lớn nhất {{sessionMax(chosen,n-1)}}°</span></div></div><p>Góc tương đối trung bình: P1–P2 {{sessionRelative(chosen,0)}}° · P2–P3 {{sessionRelative(chosen,1)}}° · P3–P4 {{sessionRelative(chosen,2)}}°</p></div>
      <div class="grid two"><div class="card"><h2>Nhật ký sự kiện</h2><p>Thời điểm, chỉ số kích hoạt và phản hồi được ghi trong phiên.</p><div v-if="!(chosen.eventLog||[]).length" class="empty">Không có sự kiện để hiển thị.</div><div v-for="(e,i) in chosen.eventLog || []" :key="i" class="event-row"><b>{{e.metric}} · {{fmt(e.peak)}}°</b><span>{{date(e.start)}} → {{date(e.end)}}</span><small>{{duration(e.end-e.start)}} · {{e.vibrated?'Đã rung demo':'Không rung'}} · Email: {{e.email}}</small><small>{{e.response}}</small></div></div>
      <div class="card"><h2>Dữ liệu & ghi chú</h2><p>Điều kiện: {{chosen.conditions || 'Chưa có thông tin'}}</p><p>Khoảng mất dữ liệu: {{(chosen.gaps || []).length ? (chosen.gaps || []).length+' khoảng' : 'Không có khoảng được ghi nhận'}}</p><p>Thông báo email: {{(chosen.eventLog || []).length ? chosen.eventLog[0].email : 'Chưa có dữ liệu'}}</p><label class="field">Ghi chú phiên <textarea v-model="noteDraft" rows="3" placeholder="Ví dụ: học trên máy tính"></textarea></label><button class="secondary" @click="dispatch({kind:'sessionNote',id:chosen.id,value:noteDraft})" :disabled="s.mode!=='demo'">Lưu ghi chú demo</button></div></div>
    </template>
  </template>
  <template v-if="page==='Progress'">
    <div v-if="s.mode==='demo'">
      <div class="period-tabs" aria-label="Khoảng thời gian"><button v-for="period in ['Phiên','Ngày','7 ngày']" :key="period" :class="{selected:progressPeriod===period}" @click="progressPeriod=period">{{period}}</button><span>Đang xem: {{progressPeriod}} · số liệu minh họa</span></div>
      <div class="section"><div><span class="eyebrow">{{progressPeriod.toUpperCase()}} · DỮ LIỆU MINH HỌA</span><h2>Tổng quan tiến trình</h2></div><span class="muted">Thống kê demo, chưa kết nối F04</span></div>
      <div class="grid metrics"><div class="card"><small>Thời gian hợp lệ</small><strong>{{periodSummary.time}}</strong><p>Trong khoảng đã chọn</p></div><div class="card"><small>Phiên đo</small><strong>{{periodSummary.sessions}} phiên</strong><p>Dữ liệu minh họa</p></div><div class="card"><small>Sự kiện vượt ngưỡng</small><strong>{{periodSummary.events}} sự kiện</strong><p>Theo ngưỡng cấu hình demo</p></div><div class="card"><small>Nhắc rung</small><strong>{{periodSummary.vibrations}} lần</strong><p>Giả lập trong khoảng đã chọn</p></div></div>
      <div class="grid two"><div class="card"><h2>Tỷ lệ thời gian vượt ngưỡng</h2><p>Phần trăm trên thời gian đo hợp lệ · theo ngày</p><div class="bar-chart"><div v-for="(v,i) in visibleRates" :key="i" class="bar-col"><b>{{v}}%</b><div class="bar-track"><i :style="{height:(v*3)+'%'}"></i></div><span>{{dayLabel(i+7-visibleRates.length)}}</span></div></div></div><div class="card"><h2>Sự kiện trên giờ hợp lệ</h2><p>Số lần vượt ngưỡng / giờ · dữ liệu minh họa</p><div class="bar-chart"><div v-for="(v,i) in visibleEvents" :key="i" class="bar-col"><b>{{v}}</b><div class="bar-track light"><i :style="{height:(v*12)+'%'}"></i></div><span>{{dayLabel(i+7-visibleEvents.length)}}</span></div></div></div></div>
      <div class="grid two"><div class="card"><h2>Xu hướng góc tương đối</h2><p>Góc trung bình từng vùng trong 7 ngày · độ (°)</p><svg class="timeline" viewBox="0 0 600 180" preserveAspectRatio="none"><line x1="0" y1="140" x2="600" y2="140" stroke="#cbd5e1"/><path v-for="(series,i) in demoAngles" :key="i" :d="demoLine(series)" fill="none" :stroke="colors[i]" stroke-width="3"/></svg><div class="legend"><span v-for="(name,i) in ['P1–P2','P2–P3','P3–P4']" :key="name" :style="{color:colors[i]}">● {{name}}</span></div></div><div class="card"><h2>Phân bố độ lệch so với mốc</h2><p>Tổng thời gian minh họa · không phải đánh giá y khoa</p><div v-for="(v,i) in [76,94,68,42,25,15]" :key="i" class="bin"><span>{{['0–5°','5–10°','10–15°','15–20°','20–25°','≥25°'][i]}}</span><div><i :style="{width:(v/94*100)+'%'}"></i></div><span>{{v}} phút · {{(v/320*100).toFixed(1)}}%</span></div></div></div>
      <div class="card"><h2>So sánh gần đây</h2><div class="comparison"><div><small>Hôm qua</small><strong>15%</strong><p>Thời gian vượt ngưỡng</p></div><div><small>Trung bình 7 ngày</small><strong>20%</strong><p>Thời gian vượt ngưỡng</p></div><div><small>Sự kiện / giờ</small><strong>3,6</strong><p>Trên thời gian hợp lệ</p></div></div><p class="muted">Số liệu trên chỉ để minh họa, không dùng để đánh giá sức khỏe.</p></div>
      <div class="grid two"><div class="card"><span class="eyebrow">DỮ LIỆU MINH HỌA</span><h2>Phản hồi sau rung</h2><p>Theo dõi chỉ số sau mỗi lần nhắc; chỉ đánh giá khi dữ liệu liên tục hợp lệ.</p><div class="response-stat"><strong>8 / 12</strong><span>lần quay về gần mốc<br>trong cửa sổ 60 giây</span></div><div class="info-row"><span>Chỉ số trước rung</span><b>18,4°</b></div><div class="info-row"><span>Chỉ số sau rung</span><b>7,2°</b></div><div class="info-row"><span>Mẫu bị loại</span><b>1 lần thiếu dữ liệu</b></div></div><div class="card"><span class="eyebrow">LƯU Ý KHI SO SÁNH</span><h2>Điều kiện đo</h2><p>Chỉ đối chiếu các phiên có vị trí gắn, khoảng cách, mốc và ngưỡng tương đối nhất quán.</p><div class="comparison-warning">Các chỉ số và phản hồi ở đây là ví dụ demo. Khi backend cung cấp thông tin khác biệt giữa các phiên, cảnh báo sẽ được hiển thị tại đây.</div><p>Độ bao phủ, cửa sổ phân tích và số mẫu loại cần được kiểm tra trước khi kết luận xu hướng.</p></div></div>
    </div><div v-else class="card"><h2>Xu hướng tư thế</h2><div class="empty">Chưa đủ dữ liệu phân tích xu hướng từ F04.</div></div>
  </template>
  <template v-if="page==='Settings'"><div class="grid two"><div class="card"><span class="eyebrow">THÔNG TIN THIẾT BỊ</span><h2>Thiết bị & cảm biến</h2><div class="info-row"><span>Device ID</span><b>{{s.deviceId||'—'}}</b></div><div class="info-row"><span>Kết nối</span><b>{{s.connection}}</b></div><div class="info-row"><span>Cập nhật gần nhất</span><b>{{date(s.updated)}}</b></div><div class="info-row" v-for="n in 4" :key="n"><span>Cảm biến P{{n}}</span><b>{{s.sensorStatus?.[n-1]==='ok'?'Hoạt động':'Không có dữ liệu'}}</b></div><p class="muted">Firmware và hiệu chuẩn sẽ hiển thị khi backend cung cấp.</p></div>
  <div class="card"><span class="eyebrow">MỐC TƯ THẾ CÁ NHÂN</span><h2>Thiết lập mốc tham chiếu</h2><p>Ngồi thoải mái, đặt chân vững, thả lỏng vai và giữ yên các cảm biến. Mốc cá nhân khác với hiệu chuẩn cảm biến.</p><div class="checklist"><span :class="{ok:s.valid}">{{s.valid?'✓':'○'}} Bốn kênh có dữ liệu hợp lệ</span><span>○ Kiểm tra hướng lắp và khoảng cách trước khi lưu</span><span>○ Độ ổn định 5–10 giây: chờ dữ liệu thiết bị thật</span></div><div v-if="s.reference" class="reference-grid"><div v-for="(p,i) in s.reference.pitch" :key="i"><small>P{{i+1}}</small><strong>{{fmt(p)}}°</strong></div></div><div v-else class="empty">Chưa có mốc được xác nhận.</div><p v-if="s.reference">Góc tương đối: {{fmt(s.reference.pitch[0]-s.reference.pitch[1])}}° · {{fmt(s.reference.pitch[1]-s.reference.pitch[2])}}° · {{fmt(s.reference.pitch[2]-s.reference.pitch[3])}}°<br>Lưu lúc {{date(s.reference.timestamp)}} · {{s.reference.deviceId}}</p><p class="muted">Nếu tháo đeo lại hoặc thay đổi vị trí, hãy kiểm tra và đặt lại mốc trước khi so sánh.</p><button @click="command('SAVE_REFERENCE')" :disabled="!!s.pending || !s.valid || s.session!=='idle'">Lưu mốc cá nhân</button></div>
  <div class="card"><span class="eyebrow">THIẾT LẬP KHOẢNG CÁCH · DEMO</span><h2>Vị trí cảm biến</h2><p>Đơn vị mm. Cấu hình dưới đây chỉ ảnh hưởng mô phỏng.</p><div class="form-grid"><label v-for="(name,i) in ['d12 · P1–P2','d23 · P2–P3','d34 · P3–P4']" :key="name">{{name}}<input type="number" min="1" v-model.number="form.distances[i]" :disabled="s.mode!=='demo'"></label></div></div>
  <div class="card"><span class="eyebrow">NHẮC NHỞ</span><h2>Chế độ rung</h2><p>Trạng thái: <b>{{s.reminder?'Đang bật':'Đang tắt'}}</b></p><div class="actions"><button @click="command('SET_REMINDER',{enabled:!s.reminder})" :disabled="!!s.pending">{{s.reminder?'Tắt':'Bật'}} nhắc rung</button><button class="secondary" @click="command('TEST_VIBRATION')" :disabled="!!s.pending">Kiểm tra rung</button></div><p>Các giá trị bên dưới là cấu hình demo, chưa gửi firmware.</p><label class="field">Chỉ số theo dõi<select v-model="form.metric" :disabled="s.mode!=='demo'"><option value="p1">Độ lệch Pitch P1 so với mốc</option><option value="q12">Thay đổi góc tương đối P1–P2</option><option value="q23">Thay đổi góc tương đối P2–P3</option><option value="q34">Thay đổi góc tương đối P3–P4</option></select></label><div class="form-grid"><label>Ngưỡng kích hoạt (°)<input type="number" min="1" v-model.number="form.trigger" :disabled="s.mode!=='demo'"></label><label>Ngưỡng kết thúc (°)<input type="number" min="0" v-model.number="form.release" :disabled="s.mode!=='demo'"></label><label>Thời gian duy trì (giây)<input type="number" min="0" v-model.number="form.hold" :disabled="s.mode!=='demo'"></label><label>Cooldown (giây)<input type="number" min="0" v-model.number="form.cooldown" :disabled="s.mode!=='demo'"></label></div><div class="info-row"><span>Chế độ viết bài · tạm dừng nhắc (demo)</span><button class="secondary small-button" @click="dispatch({kind:'writingMode',value:!s.writingMode})" :disabled="s.mode!=='demo'">{{s.writingMode?'Đang bật':'Đang tắt'}}</button></div><p class="muted">Chế độ viết chỉ là trạng thái minh họa, chưa điều khiển thiết bị.</p></div>
  <div class="card"><span class="eyebrow">THÔNG BÁO · DEMO</span><h2>Thông báo email</h2><p>Chỉ lưu lựa chọn mô phỏng, không gửi email.</p><label><input type="checkbox" v-model="form.emailEnabled" :disabled="s.mode!=='demo'"> Bật thông báo email</label><div class="form-grid"><label>Địa chỉ nhận<input type="email" placeholder="ban@example.com" v-model="form.email" :disabled="s.mode!=='demo'"></label><label>Lệch kéo dài (giây)<input type="number" min="1" v-model.number="form.emailHold" :disabled="s.mode!=='demo'"></label></div><p>Trạng thái gửi: chưa kết nối dịch vụ email.</p></div><div class="card"><h2>Lưu cấu hình demo</h2><p>Các thay đổi lưu trong bộ nhớ và mất khi khởi động lại. Cấu hình thiết bị thật đang chờ backend.</p><button @click="dispatch({kind:'demoSettings',value:form})" :disabled="s.mode!=='demo'">Lưu cấu hình demo</button></div></div></template>
</div><div v-else class="spt empty">Đang tải dữ liệu…</div>
</template>
<script>
export default {
 data(){return {progressPeriod:'7 ngày',noteDraft:'',formLoaded:false,form:{distances:[70,70,70],trigger:15,release:10,hold:30,cooldown:60,emailHold:180,metric:'p1',emailEnabled:false,email:''},demoRates:[25,23,21,24,18,15,14],demoEvents:[5.2,4.8,4.2,4.5,3.5,3.0,2.8],demoAngles:[[12,11,10,12,9,8,7],[8,9,8,7,8,7,6],[6,6,7,6,5,6,5]],showReference:true,selected:[0,1,2,3],from:'',to:'',chosen:null,names:['P1','P2','P3','P4','P1–P2','P2–P3','P3–P4'],colors:['#536a9e','#76a891','#8998d4','#c788a6','#ba715a','#4d8b82','#687688'],scenarios:[['straight','Gần thẳng'],['c','Cong C'],['s','Cong S'],['missing','Thiếu cảm biến'],['disconnect','Mất kết nối']]}},
 watch:{s:{immediate:true,handler(value){if(!this.formLoaded && value?.demoSettings){this.form={...value.demoSettings,distances:[...value.distances]};this.formLoaded=true}}}},
 computed:{periodSummary(){return this.progressPeriod==='Phiên'?{time:'42 phút',sessions:1,events:2,vibrations:1}:this.progressPeriod==='Ngày'?{time:'1 giờ 5 phút',sessions:2,events:4,vibrations:2}:{time:'5 giờ 20 phút',sessions:7,events:19,vibrations:12}},visibleRates(){return this.progressPeriod==='7 ngày'?this.demoRates:this.demoRates.slice(-1)},visibleEvents(){return this.progressPeriod==='7 ngày'?this.demoEvents:this.demoEvents.slice(-1)},s(){return this.msg?.payload},page(){return PAGE_NAME},title(){return {Dashboard:'Tổng quan',History:'Lịch sử',Progress:'Tiến trình',Settings:'Cài đặt'}[this.page]},curve(){return this.geometry(this.s?.pitch)},refCurve(){return this.geometry(this.s?.reference?.pitch)},filtered(){return (this.s.history||[]).filter(x=>{let d=new Date(x.started).toLocaleDateString('en-CA',{timeZone:'Asia/Ho_Chi_Minh'});return (!this.from||d>=this.from)&&(!this.to||d<=this.to)}).sort((a,b)=>b.started-a.started)},bins(){let a=[0,0,0,0,0,0],v=this.chosen;if(!v?.reference)return a;for(let i=1;i<v.samples.length;i++){let x=v.samples[i-1],y=v.samples[i],dt=y.t-x.t;if(x.pitch&&y.pitch&&dt>0&&dt<=2000)a[Math.min(5,Math.floor(Math.abs(x.pitch[0]-v.reference.pitch[0])/5))]+=dt}return a},binTotal(){return this.bins.reduce((a,b)=>a+b,0)}},
 methods:{timeLabel(t){return t?new Date(t).toLocaleTimeString('vi-VN',{timeZone:'Asia/Ho_Chi_Minh',hour:'2-digit',minute:'2-digit',second:'2-digit'}):'--:--'},finite(x){return Number.isFinite(x)},chooseSession(h){this.chosen=h;this.noteDraft=h.note||''},sessionMax(h,i){const a=(h.samples||[]).filter(x=>x.pitch&&Number.isFinite(x.pitch[i]));return a.length?this.fmt(Math.max(...a.map(x=>x.pitch[i]))):'\u2014'},sessionRelative(h,i){const a=(h.samples||[]).filter(x=>x.pitch&&Number.isFinite(x.pitch[i])&&Number.isFinite(x.pitch[i+1]));return a.length?this.fmt(a.reduce((v,x)=>v+x.pitch[i]-x.pitch[i+1],0)/a.length):'\u2014'},historyLine(h,i){let d='',open=false;const arr=h.samples||[];arr.forEach((x,n)=>{const v=x.pitch?.[i];if(!Number.isFinite(v)){open=false;return}const px=arr.length>1?n*600/(arr.length-1):0,py=90-v*2;d+=(open?' L ':' M ')+px+' '+py;open=true});return d},sessionAverage(h,i){const a=h.samples.filter(x=>x.pitch&&Number.isFinite(x.pitch[i]));return a.length?this.fmt(a.reduce((v,x)=>v+x.pitch[i],0)/a.length):'—'},dayLabel(i){const d=new Date(Date.now()-(6-i)*86400000);return d.toLocaleDateString('vi-VN',{timeZone:'Asia/Ho_Chi_Minh',day:'2-digit',month:'2-digit'})},demoLine(values){return values.map((v,i)=>(i?'L ':'M ')+(i*100)+' '+(150-v*7)).join(' ')},dispatch(p){this.send({payload:p})},command(c,p={}){this.dispatch({kind:'command',command:c,payload:p})},fmt(x){return Number.isFinite(x)?x.toFixed(1):'—'},date(x){return x?new Date(x).toLocaleString('vi-VN',{timeZone:'Asia/Ho_Chi_Minh'}):'—'},duration(ms){return Math.floor((ms||0)/60000)+' phút '+Math.floor((ms||0)%60000/1000)+' giây'},geometry(p){if(!p||p.length!==4||!p.every(Number.isFinite))return null;let ds=this.s.distances, x=0,y=0,pts=[[0,0]],path='M 0 0';for(let j=3;j>0;j--){let a=p[j]*Math.PI/180,b=p[j-1]*Math.PI/180,d=b-a,L=ds[j-1];for(let k=1;k<=12;k++){let u=k/12,xx,yy;if(Math.abs(d)<1e-7){xx=x+L*u*Math.sin(a);yy=y-L*u*Math.cos(a)}else{xx=x+L*(Math.cos(a)-Math.cos(a+d*u))/d;yy=y-L*(Math.sin(a+d*u)-Math.sin(a))/d}path+=' L '+xx+' '+yy;if(k===12){x=xx;y=yy}}pts.push([x,y])}return {path,points:pts}},timeline(i){let arr=this.s.samples||[],d='',open=false;arr.forEach((x,n)=>{let v=i<4?x.pitch?.[i]:x.relative?.[i-4];if(!Number.isFinite(v)){open=false;return}let px=n*600/119,py=90-v*2;d+=(open?' L ':' M ')+px+' '+py;open=true});return d}}
}
</script>
